// `journeys export-synthetics`: turns journeys that are marked `@monitor` into Elastic Synthetics journey files.
// `npx @elastic/synthetics push` bundles code, not data files, so each generated file embeds the journey text and runs
// it with journeySteps from ./adapters/synthetics.ts. The output depends on nothing but the inputs: no timestamps, a
// stable order, so a second export changes nothing in git.

import { parseHttpFile } from './http.ts';
import { parseJourney, requirementMet } from './parse.ts';
import type { JourneyMetadata } from './model.ts';

/** What the exported monitors are for: judged against each journey's `@requires`, and embedded for its `feature` blocks. */
export interface ExportContext {
  /** The feature flags that are on, kebab-case. */
  features?: string[];
  buildType?: string;
  env?: string;
  /** Turn `@alert pagerduty` into alert configuration. Without it every monitor keeps Kibana's default alerting. */
  paging?: boolean;
  /** Embedded as the base URL. Without it the generated file reads `params.url`, from `--params` or the Synthetics config. */
  baseUrl?: string;
}

export interface ExportSource {
  /** What the journey is called: its path under the export root without the extension, such as `landing/home`. */
  name: string;
  /** The file's text. */
  text: string;
  /** `journey` or `http`; `http` files are exported by the .http adapter. */
  kind?: 'journey' | 'http';
}

export interface ExportedFile {
  name: string;
  /** Relative to the output folder, such as `landing/home.journey.ts`. */
  fileName: string;
  content: string;
}

export interface ExportSkip {
  name: string;
  reason: string;
}

/** The schedules Synthetics accepts, in minutes (ALLOWED_SCHEDULES in @elastic/synthetics). */
export const SCHEDULES = [1, 2, 3, 5, 10, 15, 20, 30, 60, 120, 240];
/** The public locations Synthetics accepts. */
export const LOCATIONS = ['japan', 'india', 'singapore', 'australia_east', 'united_kingdom', 'germany', 'canada_east', 'brazil', 'us_east', 'us_west'];

/** The first words of every generated file; the CLI removes only files that start with it. */
export const GENERATED_MARKER = '// Generated by `journeys export-synthetics`';

/** Raised for a journey that cannot be exported as written, naming it. */
export class ExportError extends Error {
  readonly journey: string;

  constructor(journey: string, message: string) {
    super(`${journey}: ${message}`);
    this.name = 'ExportError';
    this.journey = journey;
  }
}

/** The generated files for the sources that are monitors and apply to the context, and why the others are not. */
export function exportSynthetics(sources: ExportSource[], context: ExportContext = {}): { files: ExportedFile[]; skipped: ExportSkip[] } {
  const files: ExportedFile[] = [];
  const skipped: ExportSkip[] = [];
  const ids = new Map<string, string>();
  for (const source of [...sources].sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))) {
    const kind = source.kind ?? 'journey';
    const text = source.text.replace(/\r\n/g, '\n');
    const metadata: JourneyMetadata | undefined = kind === 'http' ? parseHttpFile(text, source.name).metadata : parseJourney(text, source.name).metadata;
    if (!metadata?.monitor) {
      skipped.push({ name: source.name, reason: 'no @monitor' });
      continue;
    }
    if (metadata.mutates) {
      skipped.push({ name: source.name, reason: '@mutates: a monitor runs against a live site' });
      continue;
    }
    const unmet = metadata.requires?.find((r) => !requirementMet(r, context));
    if (unmet !== undefined) {
      skipped.push({ name: source.name, reason: `@requires ${unmet} does not hold` });
      continue;
    }
    const id = monitorId(source.name);
    const other = ids.get(id);
    if (other !== undefined) throw new ExportError(source.name, `its monitor id '${id}' is already taken by ${other}: rename one of them`);
    ids.set(id, source.name);
    files.push({
      name: source.name,
      fileName: `${source.name}.${kind === 'http' ? 'http.' : ''}journey.ts`,
      content: render(source.name, kind, text, metadata, context),
    });
  }
  return { files, skipped };
}

const monitorId = (name: string) => name.replace(/[^A-Za-z0-9_-]+/g, '-');

function render(name: string, kind: 'journey' | 'http', text: string, metadata: JourneyMetadata, context: ExportContext): string {
  const monitor = metadata.monitor!;
  const paging = context.paging === true && metadata.alert?.includes('pagerduty') === true;
  const tags = [...(metadata.tags ?? [])];
  if (paging) tags.push('alert:pagerduty');
  const id = monitorId(name);

  if (monitor.schedule !== undefined && !SCHEDULES.includes(monitor.schedule))
    throw new ExportError(name, `@monitor schedule=${monitor.schedule} is not one Synthetics accepts: ${SCHEDULES.join(', ')}`);
  for (const location of monitor.locations ?? [])
    if (!LOCATIONS.includes(location)) throw new ExportError(name, `@monitor location '${location}' is not a public Synthetics location: ${LOCATIONS.join(', ')}`);

  const use: string[] = [`id: ${literal(id)}`];
  if (monitor.schedule !== undefined) use.push(`schedule: ${monitor.schedule}`);
  if (monitor.locations) use.push(`locations: ${literal(monitor.locations)}`);
  if (tags.length > 0) use.push(`tags: ${literal(tags)}`);
  if (paging) use.push('alert: { status: { enabled: true } }');

  const options: string[] = [`baseUrl: ${context.baseUrl === undefined ? 'params.url' : literal(context.baseUrl)}`];
  const features = [...new Set(context.features ?? [])].sort();
  if (features.length > 0) options.push(`features: ${literal(features)}`);
  if (context.buildType !== undefined) options.push(`buildType: ${literal(context.buildType)}`);
  if (context.env !== undefined) options.push(`env: ${literal(context.env)}`);
  options.push('readOnly: true');

  const http = kind === 'http';
  return [
    `${GENERATED_MARKER} from ${name}.${http ? 'http' : 'journey'}. Do not edit: change the ${http ? 'file' : 'journey'} and export again.`,
    `import { ${http ? '' : 'expect, '}journey, monitor, step } from '@elastic/synthetics';`,
    `import { ${http ? 'httpSteps' : 'journeySteps'} } from '@nullean/journeys/synthetics';`,
    '',
    `journey({ id: ${literal(id)}, name: ${literal(name)} }, ({ ${http ? 'request' : 'page'}, params }) => {`,
    `  monitor.use({ ${use.join(', ')} });`,
    http
      ? `  httpSteps({ request, step, params }, ${template(text)}, { ${options.join(', ')} });`
      : `  journeySteps({ page, step, params, expect }, ${template(text)}, { ${options.join(', ')} });`,
    '});',
    '',
  ].join('\n');
}

/** A single-quoted string, or an array of them, as source text. */
function literal(value: string | string[]): string {
  if (Array.isArray(value)) return `[${value.map(literal).join(', ')}]`;
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n')}'`;
}

/** A template literal holding `text` exactly: backslashes, backticks and `${` are escaped. */
function template(text: string): string {
  const body = text.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${');
  return '`\n' + body.replace(/\n$/, '') + '\n`';
}
